      continue;
    }
    const kind = line[0];
    check([' ', '+', '-'].includes(kind), `Invalid diff line in ${file.filename}`);
    if (kind === '+') {
      current.firstAdded ??= { line: current.newLine, side: 'RIGHT' };
      current.newLine += 1;
      current.newSeen += 1;
      totalAdded += 1;
    } else if (kind === '-') {
      current.firstDeleted ??= { line: current.oldLine, side: 'LEFT' };
      current.oldLine += 1;
      current.oldSeen += 1;
      totalDeleted += 1;
    } else {
      current.oldLine += 1;
      current.newLine += 1;
      current.oldSeen += 1;
      current.newSeen += 1;
